#include "air_formation_internal.h"
/* $0800A6: fly-past formation followed by a persistent eight-slot manager. */
static void tick(struct EntityPool*,struct NativeEntity*,void*);
void af_schedule(struct NativeEntity*e,unsigned s){e->tick=tick;enemy_schedule(&e->payload.enemy,s);}
static void init(struct NativeEntity*e,unsigned s){uint8_t*p=(uint8_t*)&e->payload.enemy.formation;for(unsigned i=0;i<sizeof(e->payload.enemy.formation);i++)p[i]=255;e->payload.enemy.selector=65535;af_schedule(e,s);}
struct NativeEntity*af_child(struct WeaponWorld*w,struct NativeEntity*e,unsigned s,enum EntityInsert order){struct NativeEntity*n=enemy_allocate(w,entity_ref(e),order,&e->payload.enemy.actor.transform,tick);if(n)init(n,s);return n;}
void af_start(struct EnemyActor*q,unsigned n){animation_begin(&q->actor.animation,air_formation_entries[n]);q->actor.movement_flags|=32;}
void af_defense(struct EnemyActor*q,unsigned n){q->actor.defense=n==65535?0:air_formation_bindings[n].defense;q->actor.defense_count=n==65535?0:air_formation_bindings[n].count;}
int16_t af_rank(struct WeaponWorld*w,struct EnemyActor*q,unsigned n){struct InteractionWorld*r=w->interactions;if(!r||!r->rank_valid||n>=AFR_COUNT){enemy_fault(w);return 0;}unsigned i=(interaction_rank(w,&q->actor,runtime_owner_air_formation[n]))*8+(q->source_flags&3)*2;const struct AirFormationRankData*t=&air_formation_rank[n];if(t->choices)i=t->choices[i+((uint8_t)(r->player_count_flag-1)&1)]*8+((tk_random(w)&14)>>1);else i+=(r->player_count_flag&2)>>1;return (int16_t)t->values[i];}
struct Context {struct WeaponWorld*w;struct NativeEntity*e;};
static uint32_t read(void*ctx,unsigned f,unsigned width){struct Context*c=ctx;struct EnemyActor*q=&c->e->payload.enemy;if(width==2&&f==AFF_76_2)return (uint16_t)q->formation.selector;if(width==1){if(f==AFF_7E_1)return q->formation.pose;if(f==AFF_82_1)return q->formation.tilt;}enemy_fault(c->w);return 0;}
static int field(void*ctx,unsigned f,unsigned width,enum AnimationFieldOperation op,uint32_t v){struct Context*c=ctx;struct EnemyActor*q=&c->e->payload.enemy;uint32_t old=read(ctx,f,width);if(c->w->fault)return 0;if(op==AN_FIELD_AND)v&=old;else if(op==AN_FIELD_OR)v|=old;else if(op==AN_FIELD_XOR)v^=old;else if(op!=AN_FIELD_SET)return enemy_fault(c->w);if(width==2)q->formation.selector=(int16_t)v;else if(f==AFF_7E_1)q->formation.pose=(uint8_t)v;else q->formation.tilt=(uint8_t)v;return 1;}
static int bind(void*ctx,unsigned kind,uint32_t v){struct Context*c=ctx;struct EnemyActor*q=&c->e->payload.enemy;unsigned n=v==0xffffffffu?65535:v;if(n!=65535&&n>=sizeof(air_formation_bindings)/sizeof(*air_formation_bindings))return enemy_fault(c->w);if(kind==AN_DEFENSE)af_defense(q,n);else if(kind==AN_ATTACK){if(n==65535)q->actor.attack=0;else{q->attack_set=(struct HitAttackSet){air_formation_bindings[n].attack,air_formation_bindings[n].count};q->actor.attack=&q->attack_set;}hit_begin_attack(&q->actor.hit);}else return enemy_fault(c->w);return 1;}
static int sound(void*ctx,uint16_t n,int stop){struct Context*c=ctx;return c->w->sound&&c->w->sound(c->w->scene,n,stop)?1:enemy_fault(c->w);}
static int call(void*ctx,unsigned n,struct Animation*an){(void)an;struct Context*c=ctx;if(n!=AFC_283CA)return enemy_fault(c->w);hit_begin_attack(&c->e->payload.enemy.actor.hit);return 1;}
int af_animate(struct WeaponWorld*w,struct NativeEntity*e){struct WeaponActor*a=&e->payload.enemy.actor;if(a->animation.cursor==65535)return 0;struct Context c={w,e};struct AnimationOwner o={.context=&c,.read=read,.write=field,.bind=bind,.sound=sound,.call=call};int done=animation_step(&a->animation,&air_formation_program,&o);if(a->animation.fault)enemy_fault(w);return done;}
static int path_field(void*ctx,unsigned f,unsigned width,uint32_t v){struct Context*c=ctx;struct EnemyActor*q=&c->e->payload.enemy;if(width!=1)return enemy_fault(c->w);switch(f){case AFPF_3A_1:q->actor.transform.facing=v;break;case AFPF_20_1:q->actor.phase=v;break;case AFPF_21_1:q->dead=v;break;case AFPF_7F_1:q->formation.pilot=v;break;default:return enemy_fault(c->w);}return 1;}
static int path_call(void*ctx,unsigned n){struct Context*c=ctx;struct EnemyActor*q=&c->e->payload.enemy;switch(n){case AFPC_817DE:af_start(q,AFA_PATH_A);break;case AFPC_81808:af_start(q,AFA_HOP);break;case AFPC_81848:af_start(q,q->formation.pilot?AFA_ARC_RIGHT_PILOT:AFA_ARC_RIGHT);break;case AFPC_81824:af_start(q,q->formation.pilot?AFA_ARC_LEFT_PILOT:AFA_ARC_LEFT);break;case AFPC_817D0:q->formation.speed=tk_word(q->formation.speed*2);break;case AFPC_817EC:af_start(q,AFA_PATH_B);break;case AFPC_81332:if((tk_random(c->w)&15)<6)af_schedule(c->e,AF_SPLIT);break;case AFPC_817D6:q->actor.ay=64;break;case AFPC_81816:af_start(q,AFA_PATH_D);break;default:return enemy_fault(c->w);}return !c->w->fault;}
static int path_sound(void*ctx,uint16_t n){return sound(ctx,n,0);}
void af_path_begin(struct EnemyActor*q,unsigned i){q->formation.path=(struct FlightState){.cursor=air_formation_paths[i],.angle=q->selector};}
int af_path(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*q=&e->payload.enemy;struct Context c={w,e};struct FlightOwner o={.context=&c,.field=path_field,.call=path_call,.sound=path_sound};int r=flight_step(&q->actor.transform,&q->formation.path,q->formation.speed,&air_formation_flight_program,&o);q->selector=q->formation.path.angle;if(r<0)enemy_fault(w);return r;}
void af_speed(struct EnemyActor*q){unsigned angle=q->selector>>8;q->formation.speed=tk_word(((int32_t)air_formation_speed_curve[angle>>3]*q->formation.base_speed)>>8);q->formation.selector=angle>>4;}
int af_follow(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*p=tk_parent(w,e);if(!p)return 0;struct PlayerTransform*t=&e->payload.enemy.actor.transform;uint8_t group=t->display_group;*t=p->actor.transform;t->display_group=group;return 1;}
int af_outside(struct WeaponWorld*w,struct WeaponActor*a,int force){return interaction_outside(w,a,air_formation_bounds[0],force);}
int af_front_edge(struct WeaponWorld*w,struct WeaponActor*a){return tk_sx(w,a)<=32||tk_sx(w,a)>=288||tk_sy(w,a)>=512;}
int af_water(struct WeaponWorld*w,struct WeaponActor*a){return tk_sy(w,a)<=272;}
int af_surface(struct WeaponWorld*w,struct NativeEntity*e,int multiple){struct NativeEntity*n=boss_fx_spawn(w,entity_ref(e),ENTITY_FIRST_CHILD,&e->payload.enemy.actor.transform,multiple?BFX_SURFACE20:BFX_SURFACE);if(!n)return 0;n->payload.enemy.actor.transform.priority=65535;m4_screen(w,&n->payload.enemy.actor,tk_sx(w,&n->payload.enemy.actor),288);return 1;}
static unsigned random_target(struct WeaponWorld*w){unsigned p1=enemy_player_live(w->players[0]),p2=enemy_player_live(w->players[1]);return p1&&p2?(tk_random(w)&1):p2?1:0;}
static int16_t target_x(struct WeaponWorld*w,unsigned i){struct PlayerBodyState*p=i<2?w->players[i]:0;return p?tk_word((p->actor.transform.x>>8)-w->camera_x):-1;}
static int choose_route(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*q=&e->payload.enemy,*p=tk_parent(w,e);if(!p)return 0;q->formation.target=random_target(w);int x=target_x(w,q->formation.target);unsigned side=x>208?1:0;if(x>112&&x<=208)side=tk_random(w)&1;unsigned v=p->params[3];if(v>=3)v=tk_random(w);v&=3;const int16_t*t=air_formation_config[side][v];m4_screen(w,&q->actor,t[0],tk_word((int8_t)p->params[4+v]+t[1]));q->actor.transform.facing=(uint8_t)t[2];unsigned config=(uint16_t)t[3];if(config>=6)return enemy_fault(w);q->formation.config=config;af_path_begin(q,config);q->formation.base_speed=af_rank(w,q,AFR_SPEED0+config);q->formation.pose=0;q->formation.pilot=255;return !w->fault;}
static int retire(struct WeaponWorld*w,struct NativeEntity*e,int tree){struct EnemyActor*q=&e->payload.enemy,*p=tk_parent(w,e);if(!p)return 0;unsigned i=(uint16_t)q->formation.slot;if(i>=8)return enemy_fault(w);q->actor.display_flags&=253;p->formation.manager.active&=~(1u<<i);p->formation.manager.hp[i]=q->actor.hit.hp;p->formation.manager.live--;q->actor.phase=255;if(tree)entity_delete_children(w->entities,e);entity_delete(w->entities,e);return 1;}
static int killed(struct WeaponWorld*w,struct NativeEntity*e){static const uint8_t states[]={AF_SPLIT,AF_HOP,AF_SKID,AF_ARC,AF_TUMBLE,AF_TUMBLE_ALT};struct EnemyActor*q=&e->payload.enemy,*p=tk_parent(w,e);if(!p)return 0;af_defense(q,65535);q->actor.display_flags&=253;if(q->formation.pilot==1)q->formation.pilot=255;unsigned i=(uint16_t)q->formation.slot;if(i>=8||q->actor.phase>=7)return enemy_fault(w);p->params[1]--;p->formation.manager.seen&=~(1u<<i);p->formation.manager.active&=~(1u<<i);p->formation.manager.hp[i]=-1;p->formation.manager.live--;unsigned choice=air_formation_deaths[q->actor.phase][tk_random(w)&7];af_schedule(e,states[choice]);return !w->fault;}
static int enter(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;struct NativeEntity*n;struct EnemyActor*p;unsigned i;
 switch(a->state){
 case AF_SPAWN:case AF_IDLE:break; /* Pure frame entries, also reached on the next tick. */
 case AF_ROOT:a->phase=q->dead=0;i=tk_random(w)&3;if(q->params[0]>6)return enemy_fault(w);if(!q->params[0]){af_schedule(e,AF_MANAGER);return 0;}for(unsigned j=0;j<q->params[0];j++){n=af_child(w,e,AF_INTRO,ENTITY_FIRST_CHILD);if(!n)return 0;n->payload.enemy.formation.config=i;n->payload.enemy.formation.slot=j;}a->state=AF_INTRO_WAIT;break;
 case AF_MANAGER:for(i=0;i<8;i++)q->formation.manager.hp[i]=-1;q->formation.timer=0;q->formation.manager.live=q->formation.manager.seen=q->formation.manager.active=0;q->formation.manager.idle=af_rank(w,q,AFR_IDLE);q->formation.manager.period=af_rank(w,q,AFR_PERIOD);a->hit.hp=af_rank(w,q,AFR_HP);a->state=AF_SPAWN;break;
 case AF_INTRO:{unsigned c=(uint16_t)q->formation.config,j=(uint16_t)q->formation.slot;if(c>=4||j>=6)return enemy_fault(w);a->palette=0x132;q->scale_x=q->scale_y=air_formation_scales[c][j];transform_integer_offset(&a->transform,air_formation_offsets[c][j][0],air_formation_offsets[c][j][1]);q->dead=0;m4_reset(a);a->vx=-768;interaction_priority(w,a,0x1000,8);if(!j&&!tk_sound(w,0x10ba))return 0;af_start(q,AFA_INTRO);a->hit.flags&=247;if(!af_child(w,e,AF_OVERLAY_INTRO,ENTITY_FIRST_CHILD))return 0;break;}
 case AF_TURN:af_start(q,AFA_TURN);break;
 case AF_ZOOM:a->vx=tk_word((int32_t)boss_trig[1][136]*1024>>8);a->vy=tk_word((int32_t)boss_trig[0][136]*1024>>8);q->dead=0;a->ax=-32;if(!q->formation.slot&&!tk_sound(w,0x10b9))return 0;break;
 case AF_NOTIFY:p=tk_parent(w,e);if(!p)return 0;p->actor.phase++;entity_delete_children(w->entities,e);entity_delete(w->entities,e);return 0;
 case AF_APPROACH:i=(uint16_t)q->formation.config;if(i>=6)return enemy_fault(w);a->palette=0x133;m4_reset(a);m4_screen(w,a,air_formation_approach[i][0],air_formation_approach[i][1]);q->formation.base_speed=air_formation_approach[i][2];q->scale_x=q->scale_y=128;q->dead=255;interaction_priority(w,a,0x1000,12);af_path_begin(q,6+i);q->formation.pose=0;if(!tk_sound(w,0x10ba))return 0;n=boss_fx_spawn(w,entity_ref(e),ENTITY_FIRST_CHILD,&a->transform,BFX_DAMAGE_SMOKE);if(!n)return 0;n->payload.enemy.actor.attached_offset=-16;af_schedule(e,AF_APPROACH_START);return 0;
 case AF_APPROACH_START:{struct NativeEntity*owner=entity_get(w->entities,e->parent),*root=owner?entity_get(w->entities,owner->parent):0;i=(uint16_t)q->formation.slot;if(!root||root->kind!=ENTITY_ENEMY||i>=8)return enemy_fault(w);a->hit.hp=root->payload.enemy.formation.manager.hp[i];a->state=AF_APPROACH_RUN;break;}
 case AF_PLANE:a->palette=0x48;a->hit_palette=0x7d;a->display_flags|=2;interaction_priority(w,a,0xc000,20);af_defense(q,AFB_BODY);a->phase=0;if(!choose_route(w,e))return 0;n=af_child(w,e,AF_APPROACH,ENTITY_FIRST_CHILD);if(!n)return 0;n->payload.enemy.formation.slot=q->formation.slot;n->payload.enemy.formation.config=q->formation.config;n->payload.enemy.actor.hit.hp=a->hit.hp;n->payload.enemy.source_flags=0;n->payload.enemy.actor.transform.facing=0;n->payload.enemy.actor.transform.display_group=0;a->state=AF_PLANE_WAIT;break;
 case AF_PLANE_START:p=tk_parent(w,e);i=(uint16_t)q->formation.slot;if(!p||i>=8)return enemy_fault(w);a->hit.hp=p->formation.manager.hp[i];a->state=AF_PLANE_ACTIVE;break;
 case AF_RETIRED:return retire(w,e,1),0;
 case AF_OUTSIDE:return retire(w,e,0),0;
 default:return enemy_fault(w);
 }return !w->fault;
}
static void frame(struct WeaponWorld*w,struct NativeEntity*e,unsigned s){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;struct NativeEntity*n;
 if(s==AF_INTRO_WAIT){if(a->phase==q->params[0])af_schedule(e,AF_MANAGER);return;}
 if(s==AF_SPAWN||s==AF_IDLE){if(!q->params[1]){a->display_flags&=253;a->phase=255;entity_delete(w->entities,e);return;}if(s==AF_IDLE&&q->formation.manager.live)return;q->formation.timer=tk_word(q->formation.timer+1);if(q->formation.timer<(s==AF_IDLE?q->formation.manager.idle:q->formation.manager.period))return;q->formation.timer=0;if(s==AF_IDLE){af_schedule(e,AF_SPAWN);return;}unsigned i;for(i=0;i<8;i++)if((q->formation.manager.seen&(1u<<i))&&!(q->formation.manager.active&(1u<<i)))break;if(i==8)for(i=0;i<8;i++)if(!(q->formation.manager.seen&(1u<<i)))break;if(i==8){af_schedule(e,AF_IDLE);return;}n=af_child(w,e,AF_PLANE,ENTITY_FIRST_CHILD);if(!n)return;n->payload.enemy.formation.slot=i;q->formation.manager.seen|=1u<<i;q->formation.manager.active|=1u<<i;if(q->formation.manager.hp[i]==-1)q->formation.manager.hp[i]=a->hit.hp;n->payload.enemy.actor.hit.hp=a->hit.hp;q->formation.manager.live++;if((int8_t)q->formation.manager.live>=(int8_t)q->params[1]||(int8_t)q->formation.manager.live>=(int8_t)q->params[2])af_schedule(e,AF_IDLE);return;}
 if(s==AF_PLANE_WAIT){if(a->phase){n=boss_fx_spawn(w,entity_ref(e),ENTITY_FIRST_CHILD,&a->transform,BFX_DAMAGE_SMOKE);if(!n)return;n->payload.enemy.actor.attached_offset=-32;if(!af_child(w,e,AF_OVERLAY,ENTITY_FIRST_CHILD)||!af_child(w,e,AF_PILOT,ENTITY_FIRST_CHILD))return;af_schedule(e,AF_PLANE_START);}return;}
 if(s==AF_APPROACH_RUN||s==AF_PLANE_ACTIVE){af_speed(q);if(af_path(w,e)>0)af_schedule(e,s==AF_APPROACH_RUN?AF_NOTIFY:AF_RETIRED);af_animate(w,e);if(s==AF_APPROACH_RUN){static const int16_t b[]={0,1,0,1};if(interaction_outside(w,a,b,0))af_schedule(e,AF_NOTIFY);return;}if(a->hit.flags&8){a->hit.flags&=247;if(!q->dead)af_start(q,AFA_HIT);}if(!tk_hit_sound(w,a))return;if((a->hit.flags&1)&&!killed(w,e))return;if(af_outside(w,a,0))af_schedule(e,AF_OUTSIDE);return;}
 if(interaction_move(w,a,WMOVE_POINT)<0)return;
 if(s==AF_INTRO){af_animate(w,e);if(tk_sx(w,a)<224)af_schedule(e,AF_TURN);}else if(s==AF_TURN){if(af_animate(w,e))af_schedule(e,AF_ZOOM);}else if(s==AF_ZOOM){if(!q->dead&&q->scale_x>=128){q->dead=255;interaction_priority(w,a,0x1000,12);}af_animate(w,e);if(q->scale_x!=255){q->scale_x+=3;q->scale_y+=3;if(q->scale_x<=2)q->scale_x=q->scale_y=255;}}else{enemy_fault(w);return;}static const int16_t b[]={0,1,0,1};if(interaction_outside(w,a,b,0))af_schedule(e,AF_NOTIFY);
}
static void tick(struct EntityPool*p,struct NativeEntity*e,void*world){struct WeaponWorld*w=world;if(w->fault)return;struct EnemyActor*q=&e->payload.enemy;for(unsigned budget=0;budget<8;budget++){unsigned s=q->actor.state;if(s==AF_DELETE||s==AF_DELETE_TREE){if(s==AF_DELETE_TREE)entity_delete_children(p,e);entity_delete(p,e);return;}if(q->entry){q->entry=0;int r=s<AF_OVERLAY_INTRO?enter(w,e):s<AF_HOP?af_parts_enter(w,e):af_death_enter(w,e);if(!r||w->fault)return;if(r==2)continue;}if(!e->active||e->deleting)return;s=q->actor.state;if(s<AF_OVERLAY_INTRO)frame(w,e,s);else if(s<AF_HOP)af_parts_frame(w,e,s);else af_death_frame(w,e,s);return;}enemy_fault(w);}
int air_formation_spawn(struct WeaponWorld*w,struct EntityRef parent,enum EntityInsert order,const struct PlayerTransform*t,const uint8_t params[8]){struct NativeEntity*e=enemy_allocate(w,parent,order,t,tick);if(!e)return 0;init(e,AF_ROOT);if(params)for(unsigned i=0;i<8;i++)e->payload.enemy.params[i]=params[i];return 1;}
